function setupEvent()
    local event = _G.event['firstEra'].getObjects()
    if getRoundNumber()>2 then
      event = _G.event['secondEra'].getObjects()
    end

    for _, obj in ipairs(event) do
        if obj.hasTag('Event') then
            obj.shuffle()
            local dealCardNum = 0
            while dealCardNum ~=2 do
                local card = obj.takeObject({})
                if card.getGMNotes() == 'C' then
                    card.setPositionSmooth(_G.eventSlot['CHSlot'])
                elseif card.getGMNotes() == 'R' then
                    card.setPositionSmooth(_G.eventSlot['RUSlot'])
                elseif card.getGMNotes() == 'E' then
                    card.setPositionSmooth(_G.eventSlot['EUSlot'])
                elseif card.getGMNotes() == 'U' then
                    card.setPositionSmooth(_G.eventSlot['USSlot'])
                elseif dealCardNum == 0 then
                    card.setPositionSmooth(_G.eventSlot['firstPublicSlot'])
                    dealCardNum = dealCardNum + 1
                elseif dealCardNum == 1 then
                    card.setPositionSmooth(_G.eventSlot['secondPublicSlot'])
                    dealCardNum = dealCardNum + 1
                end
            end
        end
    end
end

function setupExpansion()
    for _, obj in ipairs(g('49aeaa').getObjects()) do
        if obj.hasTag('AssetCard') then
            obj.setRotationSmooth({0, 180, 180}, false, true)
            if obj.hasTag('CH') then
                obj.setPositionSmooth({43.21, 3, -16.78})
            elseif obj.hasTag('RU') then
                obj.setPositionSmooth({43.21, 3, 24.28})
            elseif obj.hasTag('EU') then
                obj.setPositionSmooth({-43.21, 3, 24.28})
            elseif obj.hasTag('US') then
                obj.setPositionSmooth({-43.21, 3, -16.78})
            end
        end
    end
    for _, obj in ipairs(g('d3eb3f').getObjects()) do
        if obj.hasTag('ActionCard') then
            obj.setPositionSmooth({-10.00, 5, 19.05})
        end
    end
    setupEvent()
    for _, zones in pairs(_G.growthZones) do
        for _, obj in ipairs(zones.getObjects()) do
            if obj.hasTag('GrowthCard') then
                obj.setPositionSmooth({-9.60, 1.80, 42.00})
            end
        end
    end
    Wait.frames(
    function()
        for _, obj in ipairs(g('086636').getObjects()) do
            if obj.hasTag('GrowthCard') then
                lv1=0
                lv2=0
                lv3=0
                lv4=0
                lv5=0
                obj.shuffle()
                while obj.getQuantity() > 1 do
                    local card = obj.takeObject({})

                    if card == nil then return end

                    local isDeck = card.getQuantity() > 1
                    local deck = card
                    if isDeck then
                        local deck = card.getObjects()
                        card = deck[#deck]
                    end

                    -- check costs
                    local cardData = getGrowthCardMetadata(isDeck and card.gm_notes or card.getGMNotes())
                    if cardData == nil then return end

                    -- check level condition
                    local level = cardData[1]

                    if card.hasTag('Type1') then
                        Z = 24.7
                    elseif card.hasTag('Type2') then
                        Z = 28.5
                    elseif card.hasTag('Type3') then
                        Z = 34
                    elseif card.hasTag('Type4') then
                        Z = 38
                    end
                    if level == 1 then
                        X = -9.6
                        lv1 = lv1 + 1
                        if lv1 > 6 then
                            X = -4.8
                            Z = 42
                        end
                    elseif level == 2 then
                        X = -4.8
                        lv2 = lv2 + 1
                        if lv2 > 4 then
                            X = -4.8
                            Z = 42
                        end
                    elseif level == 3 then
                        X = 0
                        lv3 = lv3 + 1
                        if lv3 > 4 then
                            X = -4.8
                            Z = 42
                        end
                    elseif level == 4 then
                        X = 4.8
                        lv4 = lv4 + 1
                        if lv4 > 4 then
                            X = -4.8
                            Z = 42
                        end
                    elseif level == 5 then
                        X = 9.6
                        lv5 = lv5 + 1
                        if lv5 > 2 then
                            X = -4.8
                            Z = 42
                        end
                    end
                    card.setPositionSmooth({X, 3, Z})
                end
            end
        end
    end,
    240
    )

    _G.bidButton.removeButton(2)
end

