function onObjectEnterScriptingZone(zone, object)
    if object.hasTag('ActionCard') then
        if table.contains(_G.actionDiscard, zone) then
            local rot = object.getRotation()
            if rot.z > 270 or rot.z < 90 then
                object.setRotationSmooth({0, 180, 180}, false, true)
            end
        end
    end

    -- tank and engage token labels
    if object.hasTag('Tank') or object.hasTag('EngageToken') then
        if table.contains(_G.readyArmyZones, zone) or table.contains(_G.readyEngageZones, zone) then
            -- update tank/engage count in player board
            updateArmyEngageLabels(getColorFromHegemonTag(object))
        end

        if object.hasTag('Tank') and table.contains(_G.regionScoreZone, zone) then
            -- update tank count in region zone
            updateRegionArmyCountLabels()
        end
    end

    -- country cards
    if _G.librarySetting ~= '' and _G.librarySetting ~= 'Remove' and _G.librarySetting ~= 'Static' and
    object.hasTag('CountryCard') and not object.hasTag('Starter') then
        if table.contains(_G.countryDecks, zone) then updateLibraryContent(object, 1)
        elseif table.contains(_G.countryDiscards, zone) then updateLibraryContent(object, 2)
        elseif table.contains(_G.allAllyZones, zone) then updateLibraryContent(object, 3)
        end
    end
end

function onObjectLeaveScriptingZone(zone, object)
    -- player board tank and engage token labels
    if object.hasTag('Tank') or object.hasTag('EngageToken') then
        if table.contains(_G.readyArmyZones, zone) or table.contains(_G.readyEngageZones, zone) then
            -- update tank/engage count in zone
            updateArmyEngageLabels(getColorFromHegemonTag(object))
        end

        if table.contains(_G.regionScoreZone, zone) then
            -- update tank count in region zone
            updateRegionArmyCountLabels()
        end
    end
end

