function loadLibrary()
    _G.librarySetting = _G.library.getGMNotes()
    if _G.librarySetting ~= nil and _G.librarySetting ~= '' and _G.librarySetting ~= 'Info' then
        return
    end

    -- create 4 buttons for settings
    local s = _G.libraryZone.getScale()
    for i,setting in ipairs({
        { '全部', '记录已被拿取和已出现过的盟国' },
        { '仅拿取', '记录已被拿取的盟国' },
        { '固定', '不作任何动态记录，仅作为全盟国牌库记录' },
        { '移除', '移除展示区' },
        { '信息', '这个展示区展示了游戏中所有会出现在主板图上的盟国\n\n' ..
        '拿取 (从展示区中移除) - 一个玩家已和该盟国结盟\n' ..
        '已出现 (在展示区中翻面) - 此盟国此刻在右牌堆中' } }) do

        local functionName = 'setLibrary' .. setting[1]
        _G[functionName] = function(button)
            if setting[1] == '信息' then return end
            _G.library.setGMNotes(setting[1])
            _G.librarySetting = setting[1]
            broadcastToAll('<' .. _G.librarySetting .. '> 展示区模式已选择。', _G.adminColor)
            if setting[1] == '移除' then
                for _, obj in ipairs(_G.libraryZone.getObjects()) do
                    obj.destroy()
                end
                _G.library.destroy()
                _G.libraryZone.destroy()
                return
            end
            for i = 0, 4 do
                _G.libraryZone.removeButton(i)
            end
        end
        _G.libraryZone.createButton({
            click_function = functionName,
            function_owner = self,
            label = setting[1],
            tooltip = setting[2],
            position = { -0.43, -.1, .505 - .032 * i },
            rotation = { 0, 180, 0 },
            width = 1500,
            height = 300,
            font_size = 200,
            color = { 0.5, 1, 0 },
            scale = { 1/s.x, 1/s.y, 1/s.z }
        })
    end
end

function updateLibraryContent(obj, goal)
    local setAvailable = function(name)
        local card = _G.libraryCards[name]
        if card then
            local position = card.getPosition()
            position.y = 1.9
            card.setPosition(position)
            card.setRotation({0, 180, 0})
            tryRemoveButtonWithLabel(_G.libraryZone, name:gsub("(%S+)", "%1\n"))
        end
    end
    local setPassed = function(name)
        local card = _G.libraryCards[name]
        if card then
            local position = card.getPosition()
            position.y = 1.9
            card.setPosition(position)
            card.setRotation({0, 180, 180})
            tryRemoveButtonWithLabel(_G.libraryZone, name:gsub("(%S+)", "%1\n"))
        end
    end
    local setTaken = function(name)
        local card = _G.libraryCards[name]
        if card then
            local position = card.getPosition()
            local buttonPos = _G.libraryZone.positionToLocal(position) + Vector(0, .1, -.03)
            buttonPos.x = -buttonPos.x
            position.y = 1.8
            card.setPosition(position)
            _G.libraryZone.createButton({
                click_function = "_",
                function_owner = _G.libraryZone,
                label = name:gsub("(%S+)", "%1\n"),
                position = buttonPos,
                rotation = {0, 180, 0},
                width = 0,
                height = 0,
                font_size = 100,
                font_color = {1, 1, 1},
                scale = {0.04, 0.05, 0.05}
            })
        end
    end

    local cards = {}
    if obj.getQuantity() > 1 then
        for i, card in ipairs(obj.getObjects()) do
            local data = countryCardMetadata(card.gm_notes)
            table.insert(cards, data[1])
        end
    else
        local data = countryCardMetadata(obj.getGMNotes())
        table.insert(cards, data[1])
    end

    for i, name in ipairs(cards) do
        if goal == 1 then
            setAvailable(name)
        elseif goal == 2 then
            if _G.librarySetting == '全部' then
                setPassed(name)
            elseif _G.librarySetting == '仅拿取' then
                setAvailable(name)
            end
        elseif goal == 3 then
            setTaken(name)
        end
    end
end

function tryRemoveButtonWithLabel(obj, label)
    for i, button in ipairs(obj.getButtons() or {}) do
        if button.label == label then
            obj.removeButton(i - 1)
            return
        end
    end
end

function setDuplicateCubeToLibrary(name, color)
    if _G.librarySetting == '' or _G.librarySetting == '移除' or _G.librarySetting == '固定' then
        return
    end

    local bag = _G.influenceCubeBags[color]
    if bag == nil then return end

    local card = _G.libraryCards[name]
    if card then
        local position = card.getPosition()
        position.y = 2.21
        local cube = bag.takeObject( { position = position, smooth = false } )
        cube.setScale({ .5, .5, .5 })
        cube.setLock(true)
    end
end

function checkIfZoneContains(zone, obj)
    for i, o in ipairs(zone.getObjects()) do
        if o.getQuantity() > 1 then
            for j, card in ipairs(o.getObjects()) do
                if card.guid == obj.guid then
                    return true
                end
            end
        elseif o == obj then
            return true
        end
    end
    return false
end

function useCountryForResearch(object, flip)
    local cardData = countryCardMetadata(object.getGMNotes())

    -- check whether the card is in a player's ally zone
    local color
    for playerColor, zones in pairs(_G.allyZones) do
        for i, zone in ipairs(zones) do
            for j, obj in ipairs(zone.getObjects()) do
                if obj == object then
                    color = playerColor
                    break
                end
            end
        end
    end

    if color == nil then
        broadcastToAll('国家卡必须在玩家的盟友区以用于研究。', _G.adminColor)
        return
    end

    if flip == 180 then
        -- flipped for research
        broadcastToAll(_G.hegemonName[color] .. ': +' .. cardData[5] .. ' 研究点 (' .. cardData[1] .. ')', _G.color[color])
        setResearch(color, cardData[5])
    else
        -- flipped back (undo)
        broadcastToAll(_G.hegemonName[color] .. ' 翻回了 ' .. cardData[1] .. ' ，- ' .. cardData[5] .. ' 研究点', _G.color[color])
        setResearch(color, -cardData[5])
    end
end

function getResearch()
    local researches = {}
    local data = _G.researchTable.getGMNotes()
    if data == nil then return { Yellow = 0, Blue = 0, White = 0, Red = 0 } end

    local i = 0
    local colors = { 'Yellow', 'Blue', 'White', 'Red' }
    for part in string.gmatch(data .. "/", "([^%/]*)/") do
        i = i + 1
        researches[colors[i]] = part == '-' and part or tonumber(part)
    end
    return researches
end

function setResearch(color, amount)
    local researches = getResearch()
    if researches[color] == nil or researches[color] == '-' then return end

    researches[color] = tonumber(researches[color]) + amount
    if researches[color] < 0 then
        broadcastToAll('研究点不足。', _G.color[color])
        return
    end

    data = researches['Yellow'] .. '/' .. researches['Blue'] .. '/' .. researches['White'] .. '/' .. researches['Red']
    _G.researchTable.setGMNotes(data)
    setResearchLabels()
end

function clearResearch()
    _G.researchTable.setGMNotes('-/-/-/-')
    setResearchLabels()
end

function setResearchLabels()
    local data = _G.researchTable.getGMNotes()
    if data == nil then return end

    local i = 0
    local colors = { 'Yellow', 'Blue', 'White', 'Red' }
    for part in string.gmatch(data .. "/", "([^%/]*)/") do
        i = i + 1
        _G.researchTable.editButton({ index = i - 1, label = part })
    end
end

function reorderResearchButtons(order)
    local indices = { 1, 2, 3, 4 }
    local colors = { Yellow = 1, Blue = 2, White = 3, Red = 4 }

    for i, color in ipairs(order) do
        table.remove(indices, table.indexOf(indices, colors[color]))
        _G.researchTable.editButton({
            index = colors[color] - 1,
            position = { 0, .5, (5 - 2 * i)/8 - .017 },
        })
    end

    -- unused colors are just ordered after used ones
    for i, index in ipairs(indices) do
        _G.researchTable.editButton({
            index = index - 1,
            position = { 0, .5, (5 - 2 * (i + #order))/8 - .017 },
        })
    end
end

function AddMilitaryBase(color, pos, card)
    Player[color].clearSelectedObjects()
    local rot = card.getRotation()
    if rot.z > 90 and rot.z < 270 then
        broadcastToAll('不能在一个已经消耗的盟国建立军事基地。', _G.color[color])
        return
    end

    local conditions = countryCardMetadata(card.getGMNotes())
    if getFirstObject(_G.readyArmyZones[color], 'Tank')  == nil then
        broadcastToAll('没有足够的军队以建立军事基地。', _G.color[color])
        return
    end
    local coinStorage = _G.coinManager.call('updateValue', color)
    if coinStorage < 5 then
        broadcastToAll('需要至少5$以建立军事基地', _G.color[color])
        return
    end
    if not table.contains(conditions[4], color) then
        broadcastToAll(conditions[1] .. ' 不允许 ' .. _G.hegemonName[color] .. ' 建立军事基地。', _G.color[color])
        return
    end

    _G.coinManager.call('subtractMoneyArgs', { color, 5, true, 'builds' })
    local token = _G.militaryBaseBag.takeObject()
    local position = pos + Vector(.8, 1, .8)
    token.setPosition(position)
    card.setRotationSmooth({0, 180, 180}, false, true)
    broadcastToAll('请放置影响力和军队到 ' .. _G.regionLongNames[conditions[6]] .. ' 。', _G.color[color])
end

function InvestIn(color, pos, card)
    Player[color].clearSelectedObjects()
    local rot = card.getRotation()
    if rot.z > 90 and rot.z < 270 then
        broadcastToAll('不能投资一个已经消耗的盟国。', _G.color[color])
        return
    end

    local conditions = countryCardMetadata(card.getGMNotes())
    if _G.coinManager.call('updateValue', color) < conditions[2] then
        broadcastToAll('至少需要 ' .. conditions[2] .. '$ 以投资。', _G.color[color])
        return
    end

    local token = _G.fdiTokenBag.takeObject()
    local position = pos + Vector(.1, 1, .8)
    token.setPosition(position)
    card.setRotationSmooth({0, 180, 180}, false, true)
    _G.coinManager.call('subtractMoneyArgs', { color, conditions[2], true, 'invests' })
    broadcastToAll('请放置影响力到 ' .. _G.regionLongNames[conditions[6]] .. ' 。', _G.color[color])
end

function tryTakeEngageForCoin(color, pos, obj)
