function getAllyCountForRegion(color, region)
    count = 0
    for i,zone in ipairs(_G.allyZones[color]) do
        local allyCard = getFirstObject(zone, 'CountryCard')
        if allyCard ~= nil then
            local allyRegion = countryCardMetadata(allyCard.getGMNotes())[6]
            if allyRegion == region then count = count + 1 end
        end
    end
    return count
end

function countryCardMetadata(cardGMNotes)
    local parts = {}
    for i,part in ipairs(splitString(cardGMNotes, '-')) do
        table.insert(parts, part)
    end
    local data = {}
    data[1] = parts[1]              -- name
    data[2] = tonumber(parts[2])    -- FDI cost
    data[3] = {}                    -- banned allies for
    data[4] = {}                    -- allowed bases for (blank = none)
    data[5] = tonumber(parts[5])    -- Diplomacy value
    data[6] = parts[6]              -- region
    if parts[3] ~= nil then
        for i=1,#parts[3] do
            local hegemon = string.sub(parts[3], i, i)
            table.insert(data[3], getColorByCharacter(hegemon))
        end
    end

    if parts[4] ~= nil then
        for i=1,#parts[4] do
            local hegemon = string.sub(parts[4], i, i)
            table.insert(data[4], getColorByCharacter(hegemon))
        end
    end

    return data
end

function improveRelations(args)
    local color = args[1]
    local region = args[2]
    local zones = args[3] and _G.countryDecks or _G.countryDiscards
    local zone = zones[region]

    if zones[region] == nil then
        -- this should never happen
        return
    end

    local card = getFirstObject(zone, 'CountryCard')
    if card == nil then return end

    local isDeck = card.getQuantity() > 1
    local deck = card
    if isDeck then
        local deck = card.getObjects()
        card = deck[#deck]
    end

    local cardData = countryCardMetadata(isDeck and card.gm_notes or card.getGMNotes())

    if cardData == nil then
        broadcastToAll('无法获取该国家的自动化信息。请手动进行更改。', _G.adminColor)
        return
    end

    if table.contains(cardData[3], color) then
        broadcastToAll(_G.hegemonName[color] .. ' 不能与 ' .. cardData[1] .. ' 改善关系。', _G.adminColor)
        return
    end

    -- player is able to get this card, search for a duplicate on the board or best empty
    -- best empty order:
    --- a zone next to a card of the same region in the direction stated at the array definition (Yellow/Blue: left, White/Red: right)
    --- if none, the first empty zone below/above a card of the same region (going from the opposite direction)
    --- if none, the closest column from starting point, where there are no cards in the 3 zones to the opposite direction
    --- if none, the first empty zone from opposite direction
    --- if none, give up (max 32 allies supported)
    local goalZone, duplicate = getBestAllyZone(color, cardData)

    if goalZone == nil then
        broadcastToAll('当前支持的最大盟友数量为32个。\n请手动继续操作，并修正任何与盟友数量相关的计分问题。', _G.adminColor)
        return
    end

    local position = goalZone.getPosition()
    position.y = position.y + .5
    if duplicate ~= nil then

        -- if the card is in the upper slot, move it down
        local duplicatePos = duplicate.getPosition()
        if duplicatePos.z > position.z - .5 then
            duplicatePos.z = position.z - .84
            duplicate.setPosition(duplicatePos)
        else
            -- if there are tokens, move them above
            local fdiToken = getFirstObject(goalZone, 'FDIToken')
            local baseToken = getFirstObject(goalZone, 'MilitaryBaseToken')
            if fdiToken ~= nil then
                local pos = fdiToken.getPosition()
                pos.y = pos.y + 1
                pos.z = pos.z + .84
                fdiToken.setPosition(pos)
            end
            if baseToken ~= nil then
                local pos = baseToken.getPosition()
                pos.y = pos.y + 1
                pos.z = pos.z + .84
                baseToken.setPosition(pos)
            end
        end

        local rotation = duplicate.getRotation()
        if (rotation.z < 90 or rotation.z > 270) then
            broadcastToAll('添加1影响力到 ' .. _G.regionLongNames[cardData[6]] .. ' 因为你与该地区你的已准备初始盟国改善了关系。', _G.color[color])
        end
    else
        position.z = position.z - .84
    end

    if isDeck then card = deck.takeObject() end
    card.setPosition(position)

    local duplicateCubeColor = getColorFromHegemonTag(card)
    if duplicateCubeColor ~= nil then
        setDuplicateCubeToLibrary(cardData[1], color)
    end

    -- if the zone had only one card, refresh
    if not isDeck then dealCountry(region) end

    broadcastToAll('与 ' .. cardData[1] .. ' (' .. cardData[5] .. ' 外交) 改善关系。', _G.color[color])
end

function getBestAllyZone(color, cardData)
    local name = cardData[1]
    local region = cardData[6]
    local sameRegionAlly = function(zone, region)
        local ally = getFirstObject(zone, 'CountryCard')
        if ally ~= nil then
            local allyData = countryCardMetadata(ally.getGMNotes())
            if allyData ~= nil and allyData[6] == region then
                return zone
            end
        end
        return nil
    end

    -- first pass: look for duplicates
    for i, zone in ipairs(_G.allyZones[color]) do
        local ally = getFirstObject(zone, 'CountryCard')

        if ally ~= nil then
            local allyData = countryCardMetadata(ally.getGMNotes())
            if allyData ~= nil and allyData[1] == name then
                return zone, ally
            end
        end
    end

    -- second pass: look for empty zones next to a card of the same region
    for i = #_G.allyZones[color], 1, -1 do
        local zone = _G.allyZones[color][i]
        local isEmpty = getFirstObject(zone, 'CountryCard') == nil

        if isEmpty then
            local forwardIndex = i + 2
            if forwardIndex <= #_G.allyZones[color] then
                local ally = sameRegionAlly(_G.allyZones[color][forwardIndex], region)
                if ally ~= nil then return zone end
            end

            local backwardIndex = i - 2
            if backwardIndex >= 1 then
                local ally = sameRegionAlly(_G.allyZones[color][backwardIndex], region)
                if ally ~= nil then return zone end
            end
        end
    end

    -- third pass: look for empty zones below/above a card of the same region (opposite direction)
    for i = #_G.allyZones[color], 1, -1 do
        local zone = _G.allyZones[color][i]
        local isEmpty = getFirstObject(zone, 'CountryCard') == nil

        if isEmpty then
            local belowIndex = i + 1
            if belowIndex % 2 == 0 then
                local ally = sameRegionAlly(_G.allyZones[color][belowIndex], region)
                if ally ~= nil then return zone end
            end

            local aboveIndex = i - 1
            if belowIndex % 2 == 1 then
                local ally = sameRegionAlly(_G.allyZones[color][aboveIndex], region)
                if ally ~= nil then return zone end
            end
        end
    end

    -- fourth pass: look for empty zones in columns without cards
    for i = 7, #_G.allyZones[color] do
        local zone = _G.allyZones[color][i]
        local isEmpty = getFirstObject(zone, 'CountryCard') == nil

        if isEmpty then
            -- if 1 column to the left are empty, take this one
            if getFirstObject(_G.allyZones[color][i - 2], 'CountryCard') == nil and
               getFirstObject(_G.allyZones[color][i - 4], 'CountryCard') == nil and
               getFirstObject(_G.allyZones[color][i - 6], 'CountryCard') == nil then
                return zone
            end
        end
    end

    -- fifth pass: take the first empty zone
    for i, zone in ipairs(_G.allyZones[color]) do
        local isEmpty = getFirstObject(zone, 'CountryCard') == nil

        if isEmpty then
            return zone
        end
    end

    return nil
end

function getCountryZones()
