    end
    return zones
end

function table.contains(tbl, value)
    if tbl == nil then return false end
    for _, v in pairs(tbl) do
        if v == value then
            return true
        end
    end
    return false
end

function table.indexOf(array, value)
    for i, v in ipairs(array) do
        if v == value then
            return i
        end
    end
    return nil
end

function getColorByCharacter(character)
