    for _, obj in ipairs(zone.getObjects()) do
        if obj.hasTag(tag) then
            return obj  -- Return the first object with the specified tag
        end
    end
    return nil  -- Return nil if no object with the tag is found
end

function checkIfZoneHas(zone, tag)
    for _, obj in ipairs(zone.getObjects()) do
        if obj.hasTag(tag) then return true end
    end
    return false
end

function placeCard(fromZone, toZone, tag, rotate, isSmooth)
    local smooth = isSmooth == nil or isSmooth
    local card = getFirstObject(fromZone, tag)
    if card == nil then return end

    -- if object is a deck, take the top card
    if card.getQuantity() > 0 then
        card = card.takeObject()
    end

    local pos = toZone.getPosition()
    if smooth then
        card.setPositionSmooth({pos.x, pos.y + 1, pos.z}, false, true)
    else
        card.setPosition({pos.x, pos.y + 1, pos.z})
    end
    if rotate then
        local rot = card.getRotation()
        card.setRotationSmooth({rot.x, rot.y, rot.z + 180}, false)
    end

    return card
end

