function placeCardAndRefill(fromZone, toZone, tag, rotate, shuffle)
    -- put a card from left-to-right
    Wait.time(function() placeCard(fromZone, toZone, tag, rotate) end, .33)
    Wait.time(
        function()
            local card = getFirstObject(fromZone, tag)
            if card == nil then
                local discard = getFirstObject(toZone, tag)
                if discard == nil then return nil end
                local pos = fromZone.getPosition()
                discard.setPositionSmooth({pos.x, pos.y + 1, pos.z}, false, true)
                if shuffle then discard.shuffle() end
                Wait.time(function() placeCard(fromZone, toZone, tag, rotate) end, .66)
            end
        end,
        .66)
end

function getGrowthCard(args)
    local color = args[1]
    local zone = args[2]
    local card = getFirstObject(zone, 'GrowthCard')
    if card == nil then return end

    local isDeck = card.getQuantity() > 1
    local deck = card
    if isDeck then
        local deck = card.getObjects()
        card = deck[#deck]
    end

    -- check costs
    local cardData = getGrowthCardMetadata(isDeck and card.gm_notes or card.getGMNotes())
    if cardData == nil then return end

    -- check level condition
    local level = cardData[1]
    local nextLevel = 1

    for i,boughtZone in ipairs(_G.growthCards[color]) do
        if getFirstObject(boughtZone, 'GrowthCard') == nil then
            nextLevel = i
            break
        end
    end

    if level ~= nextLevel then
        broadcastToAll('你现在只能获取 ' .. nextLevel .. ' 级发展卡。', _G.color[color])
        return
    end

    local amount = cardData[3]
    local resource = cardData[4]

    local servicesInInventory = getResourceCount(color, 'Services')
    if servicesInInventory == nil then return end
    servicesInInventory = servicesInInventory[1]

    local resourceInInventory = _G.coinManager.call('updateValue', color)
    if resource == 'Diplomacy' or resource == 'Goods' then
        resourceInInventory = getResourceCount(color, resource)
        if resourceInInventory == nil then return end
        resourceInInventory = resourceInInventory[1]
    end
    if resource == 'Army' then
        resourceInInventory = getResourceCount(color, resource)
        if resourceInInventory == nil then return end
    end
    if resource == 'Services' then
        level = level+amount
        amount = 0
    end

    if servicesInInventory < level or resourceInInventory < amount then
        broadcastToAll('你无法支付这张卡的费用。', _G.color[color])
        return
    end

    -- remove resources and get card
    produce(color, 'Services', -level, true, false, false, 'grows')
    produce(color, resource, -amount, true, false, false, 'grows')

    local position = _G.growthCards[color][nextLevel].getPosition()
    position.y = position.y + 1
    if isDeck then card = deck.takeObject() end

    if level == 4 then
      if card.hasTag('Type3') then
        cardData[2] = getRoundNumber()*2-2
      end
    end

    moveVPMarkerBy(color, cardData[2], 'for Growth Card')
    card.setPosition(position, false, true)
    card.setRotation({ 0, 180, level <= getRoundNumber() and 0 or 180 }, false, true)
end

function getGrowthCardMetadata(data)
    if data == nil or data == '' then return nil end
    local parts = {}
    for i,part in ipairs(splitString(data, '-')) do
        table.insert(parts, part)
    end
    local data = {}
    data[1] = tonumber(parts[1])            -- level
    data[2] = tonumber(parts[2])            -- VP
    data[3] = tonumber(string.sub(parts[3], 1, -2))   -- cost
    if string.sub(parts[3], -1, -1) == 'C' then
        data[4] = 'Coins'
    elseif string.sub(parts[3], -1, -1) == 'D' then
        data[4] = 'Diplomacy'
    elseif string.sub(parts[3], -1, -1) == 'T' then
        data[4] = 'Army'
    elseif string.sub(parts[3], -1, -1) == 'G' then
        data[4] = 'Goods'
    elseif string.sub(parts[3], -1, -1) == 'S' then
        data[4] = 'Services'
    end
    return data
end

function researchCard(args)
    local isResearchPhase = _G.phaseManager.call('isPhaseResearch')
    local isActionPhase = _G.phaseManager.call('isPhaseAction')

    if not (isResearchPhase or isActionPhase) then
        return
    end

    local playerColor = args[1]
    local marketIndex = args[2]

    local zone = _G.market[marketIndex]
    local card = getFirstObject(zone, 'ActionCard')
    if card == nil then return end

    local cardData = card.getGMNotes()
    if card.getQuantity() > 1 then
        cardData = card.getObjects()[#card.getObjects()].gm_notes
    end

    local cost = tonumber(string.sub(cardData, 4, 4))

    if isActionPhase then
        if cost > 6 then
            broadcastToAll('无法使用最小化官僚研发此牌。', _G.color[playerColor])
            return
        else
            broadcastToAll(_G.hegemonName[playerColor] .. ' 使用最小化官僚进行了研发。', _G.color[playerColor])
        end
    else
        local researches = getResearch()
        if researches[playerColor] == nil or researches[playerColor] == '-' then
            return
        elseif researches[playerColor] < cost then
            broadcastToAll('研究点不足。', _G.color[playerColor])
            return
        else
            setResearch(playerColor, -cost)
        end
    end

    local deckZone = _G.actionDeck[playerColor]
    placeCard(zone, deckZone, 'ActionCard', isResearchPhase, false)
    refillMarket(marketIndex)
end

function refillMarket(marketIndex)
    for i = marketIndex,2,-1 do
        placeCard(_G.market[i - 1], _G.market[i], 'ActionCard', false)
    end
end

function dealAutoInfluence()
    placeCard(_G.autoInfluenceDeck, _G.autoInfluence1, 'autoInfluenceCard', true)
    placeCard(_G.autoInfluenceDeck, _G.autoInfluence2, 'autoInfluenceCard', true)
end

function doAutoInfluence()
    local cards = {
        getFirstObject(_G.autoInfluence1, 'autoInfluenceCard'),
        getFirstObject(_G.autoInfluence2, 'autoInfluenceCard')
    }

    local colors = { 'Blue', 'Yellow', 'White', 'Red' }

    for x, card in pairs(cards) do
        Wait.time(
            function()
                local gm_notes = card.getGMNotes()

                local influence = ''
                local tanksOrTrade = ''
                for part in string.gmatch(gm_notes, "([^%-]+)") do
                    if influence == '' then
                        influence = part
                    else
                        tanksOrTrade = part
                    end
                end

                for i = 1, #influence do
                    local char = string.sub(influence, i, i)
                    local color = colors[i]
                    if not _G.humanPlayers[color] then

                        addInfluence({char, color, not isRegionFullyInfluenced(char), false})

                        local action = string.sub(tanksOrTrade, i, i)

                        -- action is T for tank, or hegemon letter for trade
                        if action == 'T' then
                            addArmy({char, color, true, false})
                        elseif action ~= 'x' then
                            local tradeTo = getColorByCharacter(action)
                            if _G.humanPlayers[tradeTo] then
                                local card = freshCommerceCard(tradeTo)
                                if card ~= nil then
                                    local rot = card.getRotation()
                                    rot.z = 180
                                    card.setRotationSmooth(rot, false, true)
                                    broadcastToAll('Auto-Influence: ' .. _G.hegemonName[tradeTo] .. ' flips Commerce Card for AI trade.', _G.color[tradeTo])
                                    _G.coinManager.call('addMoneyArgs', { tradeTo, 10, true, 'sells' })
                                else
                                    broadcastToAll('Auto-Influence: No Commerce Card to flip for 10$.', _G.color[tradeTo])
                                end
                            end
                        end
                    end
                end

                placeCard(x == 1 and _G.autoInfluence1 or _G.autoInfluence2, _G.autoInfluenceDiscard, 'autoInfluenceCard', true)
            end,
            x)
    end
    Wait.time(dealAutoInfluence, 3) -- after evaluating, deal 2 new cards
end

function advanceRoundMarker()
    local pos = _G.roundMarker.getPosition()
    _G.roundMarker.setPositionSmooth({pos.x, pos.y, pos.z + 1.25}, false, true)
end

function getRoundNumber()
    local thresholds = {-7.1, -5.9, -4.7, - 3.5, -2.0, -1.1}
    local posZ = _G.roundMarker.getPosition().z

    for i, threshold in ipairs(thresholds) do
        if posZ < threshold then
            return i
        end
    end

    return #thresholds
end

function addArmy(args)
    local region = args[1]
    local playerColor = args[2]
    local fromSupply = args[3]
    local isPaid = args[4]

    local zone = _G.regionScoreZone[region]

    local tank = fromSupply and
        _G.tankBags[playerColor].takeObject() or
        getFirstObject(_G.readyArmyZones[playerColor], 'Tank')

    if (tank == nil) then
        broadcastToAll('你的军队不足。', playerColor)
        return nil
    end

    if _G.humanPlayers[playerColor] then
        -- check cost of placement
        if isPaid then
            local coinStorage = _G.coinManager.call('updateValue', playerColor)
            if coinStorage < 5 then
                broadcastToAll('缺少5$以移动军队。', playerColor)
                return nil
            end
        end

        -- clicked by user, check if tanks can be added (ZOI or Base in regional ally)
        local canPlace = table.contains(_G.zoneOfInterests[playerColor], region)
        if not canPlace then
            for i,zone in ipairs(_G.allyZones[playerColor]) do
                local milToken = getFirstObject(zone, 'MilitaryBaseToken')
                if milToken ~= nil then
                    local card = getFirstObject(zone, 'CountryCard')
                    local data = countryCardMetadata(card.getGMNotes())
                    if data ~= nil then
                        if data[6] == region then canPlace = true end -- token with regional card found
                    end
                end
            end
            if not canPlace then
                broadcastToAll('因非相关区且无军事基地无法向 ' .. _G.regionLongNames[region] .. '移动军队。', _G.adminColor)
            end
        end
    end

    if tank.getQuantity and tank.getQuantity() > 1 then
        tank = tank.takeObject()
    end

    local pos = _G.regionArmySpots[region]
    local offset = _G.tankOffsets[playerColor]
    tank.setPosition({pos[1] + offset[1], pos[2], pos[3] + offset[3]})

    if _G.humanPlayers[playerColor] and isPaid then
        produce(playerColor, 'Coins', -5, true, false, true, 'moves')
    end

    return tank
end

function addInfluence(args)
    local region = args[1]
    local playerColor = args[2]
    local permanent = args[3]
    local alt = args[4]

    if alt then
        if permanent then
            promoteInfluence(region, playerColor)
        else
            resetInfluence(region, playerColor)
        end
        return
    end

    local zones = _G.influenceZones[region][permanent and 'P' or 'T']
    local spotIndex = getEmptyInfluenceSpotIndex(region, permanent)
    local cube = _G.influenceCubeBags[playerColor].takeObject()

    if spotIndex ~= nil then
        local score = permanent and 1 or _G.influenceZones[region]['S'][spotIndex]
        moveVPMarkerBy(playerColor, score, 'for added influence')

        local pos = zones[spotIndex].getPosition()
        cube.setPositionSmooth({pos.x, 3, pos.z}, false, true)
    else
        if permanent then
            cube.setPositionSmooth(influenceExtraSpots[region], false, true)
        else
            for i = 1, #zones do
                local c = getFirstObject(zones[i], 'InfCube')
                if i == 1 then
                    destroyObject(c)
                else
                    local poss = zones[i-1].getPosition()
                    c.setPositionSmooth({poss.x, 3, poss.z}, false, true)
                end
            end
            local poss = zones[#zones].getPosition()
            cube.setPositionSmooth({poss.x, 3, poss.z}, false, true)
        end
    end
end

function promoteInfluence(region, playerColor)
    local cube, index = getFirstTemporaryCubeOfColor(region, playerColor)
    if cube == nil or index == nil then return end

    local zone = _G.influenceZones[region]['P']
    local permaSpotIndex = getEmptyInfluenceSpotIndex(region, true)
    if permaSpotIndex == nil then
        cube.setPositionSmooth(influenceExtraSpots[region], false, true)
    else
        local pos = _G.influenceZones[region]['P'][permaSpotIndex].getPosition()
        cube.setPositionSmooth({pos.x, 3, pos.z}, false, true)
    end

    -- shift temporary to the left
    shiftTemporaryInfluenceLeft(region, index + 1)
end

function resetInfluence(region, playerColor)
    local cube, index = getFirstTemporaryCubeOfColor(region, playerColor)
    if cube == nil or index == nil then return end

    -- get last filled temporary spot
    local tempSpotIndex = 0
    for i = 1, #_G.influenceZones[region]['T'] do
        if not checkIfZoneHas(_G.influenceZones[region]['T'][i], 'InfCube') then
            tempSpotIndex = i - 1
            break
        end
        if i == #_G.influenceZones[region]['T'] then
            tempSpotIndex = i
        end
    end

    if tempSpotIndex == 0 then return end -- no cubes in temporary
    local pos = _G.influenceZones[region]['T'][tempSpotIndex].getPosition()
    cube.setPositionSmooth({pos.x, 3, pos.z}, false, true)

    -- shift temporary to the left
    shiftTemporaryInfluenceLeft(region, index + 1)
end

function getFirstTemporaryCubeOfColor(region, playerColor)
    local zones = _G.influenceZones[region]['T']
    for i, zone in ipairs(zones) do
        local cube = getFirstObject(zone, 'InfCube')
        if cube == nil then return nil, nil end
        if getColorFromHegemonTag(cube) == playerColor then
            return cube, i
        end
    end
    return nil, nil
end

function shiftTemporaryInfluenceLeft(region, fromIndex)
    local zones = _G.influenceZones[region]['T']
    for i = fromIndex, #zones do
        local cube = getFirstObject(zones[i], 'InfCube')
        if cube ~= nil then
            local pos = zones[i - 1].getPosition()
            cube.setPositionSmooth({pos.x, 3, pos.z}, false, true)
        end
    end
end

function isRegionFullyInfluenced(region)
    local zones = _G.influenceZones[region]['P']
    return checkIfZoneHas(zones[#zones], 'InfCube')
end

function getEmptyInfluenceSpotIndex(region, permanent)
    local zones = _G.influenceZones[region][permanent and 'P' or 'T']
    local index = 1
    for _, zone in ipairs(zones) do
        if not checkIfZoneHas(zone, 'InfCube') then
            return index
        end
        index = index + 1
    end
    return nil
end

function getScore(playerColor)
    local position = _G.VPToken[playerColor].getPosition()
    local closestIndex = 0
    local closestDistance = math.abs(_G.VPTokenPositions[0][1] - position[1]) + math.abs(_G.VPTokenPositions[0][3] - position[3])

    for i = 1, 99 do
        local dx = math.abs(_G.VPTokenPositions[i][1] - position[1])
        local dz = math.abs(_G.VPTokenPositions[i][3] - position[3])
        local distance = dx + dz  -- Manhattan distance in X and Z

        if distance < closestDistance then
            closestDistance = distance
            closestIndex = i
        end
    end

    local rotation = _G.VPToken[playerColor].getRotation()
    local over100 = (rotation.z > 90 and rotation.z < 270)
    if over100 then
        closestIndex = closestIndex + 100
    end

    return closestIndex
end

function moveVPMarkerBy(playerColor, moveBy, reasonText)
    local vpToken = _G.VPToken[playerColor]
    if vpToken == nil then return nil end

    local score = getScore(playerColor)
    broadcastToAll(_G.hegemonName[playerColor] .. " scores: " .. (moveBy > 0 and '+' or '') .. moveBy .. "VP " .. reasonText, _G.color[playerColor])

    local newVP = math.max(0, score + moveBy) -- players cannot go below 0 score
    vpToken.setPositionSmooth(_G.VPTokenPositions[newVP % 100], false, true)
    vpToken.setRotation({0, 0, (0 + newVP > 99) and 180 or 0}, false, true)
end

function resolveThreat()
    local focuses = checkHegemonFocuses()

    local delay = 1
    -- go through all regions
    for regionChar, regionZone in pairs(_G.regionScoreZone) do
        local tanksByColor = getArmyCounts(regionZone)
        local defenseByColor = getDefenseCounts(regionZone)

        local losses = {}

        -- check for all players
        for playerColor, isHuman in pairs(_G.humanPlayers) do
            -- check whether player has ZOI in this region
            if isHuman and table.contains(_G.zoneOfInterests[playerColor], regionChar) then
                local losing = 0
                for otherColor, tanks in pairs(tanksByColor) do
                    if otherColor ~= playerColor and not natoMembers(playerColor, otherColor) then
                        local defense = defenseByColor[playerColor] + tanksByColor[playerColor] or 0
                        local threat = tanks + (focuses[otherColor] == 'Military' and tanks > 0 and 1 or 0)
                        if getRoundNumber()>4 then
                            if _G.humanPlayers[playerColor] == true then
                                if getFirstObject(_G.growthCards[playerColor][5], 'GrowthCard')~= nil then
                                    if getFirstObject(_G.growthCards[playerColor][5], 'GrowthCard').hasTag('Type3') then
                                        defense = defense+1
                                    end
                                end
                            end
                            if _G.humanPlayers[otherColor] == true then
                                if getFirstObject(_G.growthCards[otherColor][5], 'GrowthCard')~= nil then
                                    if getFirstObject(_G.growthCards[otherColor][5], 'GrowthCard').hasTag('Type3') then
                                        threat = threat+1
                                    end
                                end
                            end
                        end
                        if threat > defense then
                            losing = losing + 2
                            if playerColor == 'Blue' and otherColor == 'White' and cheakGlobleEffect('NS') then
                              losing = losing - 1
                            end
                            if otherColor == 'Blue' and playerColor == 'White' and cheakGlobleEffect('NS') then
                              losing = losing - 1
                            end
                            if playerColor == 'Red' and otherColor == 'White' and cheakGlobleEffect('CR') then
                              losing = losing - 2
                            end
                            if otherColor == 'Red' and playerColor == 'White' and cheakGlobleEffect('CR') then
                              losing = losing - 2
                            end
                        end
                    end
                end
                if losing > 0 then
                    losses[playerColor] = losing
                end
            end
        end

        -- if there are losses, apply them after a delay
        if next(losses) ~= nil then
            Wait.time(
                function()
                    printToAll('--- 在 ' .. _G.regionLongNames[regionChar] .. ' 解决威胁 ---')
                    for playerColor, losing in pairs(losses) do
                        moveVPMarkerBy(playerColor, -losing, 'for being threatened in ' .. _G.regionLongNames[regionChar])
                    end
                end, delay
            )
            delay = delay + 1
        end

    end

    return delay
end

function natoMembers(color1, color2)
    local nato = { 'Yellow', 'Blue' }
    return table.contains(nato, color1) and table.contains(nato, color2)
end

function scoreInfluence()
    local scores = {}

    local regions = getRegionCounts(true)

    for region,colors in pairs(regions) do
        scores[region] = {}
        for color,cubes in pairs(colors) do
            scores[region][color] = {}
            scores[region][color]['InfCube'] = cubes
            scores[region][color]['Majority'] = 0
        end

        -- InfCubes are counted up, calculate majority within region
        local tankCounts = getArmyCounts(_G.regionScoreZone[region])
        for color in pairs(colors) do
          if getRoundNumber()>4 then
            if color ~= 'Black' then
              if _G.humanPlayers[color] == true then
                if getFirstObject(_G.growthCards[color][5], 'GrowthCard')~= nil then
                  if getFirstObject(_G.growthCards[color][5], 'GrowthCard').hasTag('Type4') then
                    tankCounts[color] = 99
                  end
                end
              end
            end
          end
        end

        calculateInfluenceMajority(scores[region], _G.regionInfluenceMajorityScores[region], tankCounts)
    end

    -- for now add scores per player instantly
    local totalScores = {}

    for region,player in pairs(scores) do
        for color,parts in pairs(player) do
            if _G.humanPlayers[color] then
                if totalScores[color] == nil then totalScores[color] = 0 end
                for _,score in pairs(parts) do
                    totalScores[color] = totalScores[color] + score
                end
            end
        end
    end

    for color,score in pairs(totalScores) do
        moveVPMarkerBy(color, score, 'for influence')
    end
end

function calculateInfluenceMajority(scores, regionalMajorityScores, tankCounts)
    -- Create a list of players and their cube counts for sorting
    local cubeCounts = {}
    for color, data in pairs(scores) do
        table.insert(cubeCounts, {color = color, InfCube = data.InfCube, tankCount = tankCounts[color]})
    end

    -- Sort players by descending cube count and tankCount
    table.sort(cubeCounts, function(a, b)
        if a.InfCube ~= b.InfCube then
            return a.InfCube > b.InfCube
        else
            return a.tankCount > b.tankCount
        end
    end)

    -- Assign scores based on ranks and handle ties
    local currentScoreIndex = 1
    local i = 1
    while i <= #cubeCounts do
        local start = i
        -- Find end of tie group with same InfCube count
        while i + 1 <= #cubeCounts and
              cubeCounts[i].InfCube == cubeCounts[i + 1].InfCube and
              cubeCounts[i].tankCount == cubeCounts[i + 1].tankCount do
            i = i + 1
        end
        local tieCount = i - start + 1

        -- Determine score to assign for this tie group
        local scoreToAssign = 0
        if currentScoreIndex + tieCount - 1 <= #regionalMajorityScores then
            scoreToAssign = regionalMajorityScores[currentScoreIndex + tieCount - 1]
        else
            scoreToAssign = 0
        end

        -- Assign score to each player in the tie group
        for j = start, i do
            local counts = cubeCounts[j]
            scores[counts.color].Majority = counts.InfCube > 0 and scoreToAssign or 0   -- tie with 0 cubes score a 0
        end

        -- Move to the next group in the scoring table
        currentScoreIndex = currentScoreIndex + tieCount
        i = i + 1
    end
end

