function splitString(input, delimiter)
    local result = {}
    local current = ""

    for i = 1, #input do
        local char = input:sub(i, i)
        if char == delimiter then
            table.insert(result, current)
            current = ""
        else
            current = current .. char
        end
    end

    -- Add the last part
    table.insert(result, current)

    return result
end

