function superpowerOverstretch()
    if not _G.humanPlayers['Blue'] then return end -- no US player

    local regions = getRegionCounts(false)
    local losingRegions = {}
    local message = ''

    for region,colors in pairs(regions) do
        local max = -1
        local usCubes = 0
        for color,cubes in pairs(colors) do
            if color == 'Blue' then usCubes = cubes end
            if cubes > max then max = cubes end
        end
        if usCubes < max then
            table.insert(losingRegions, region)
            message = message .. _G.regionLongNames[region] .. ', '
        end
    end
    message = string.sub(message, 1, #message - 2)

    local vpMinus = { -12, -8, -5, -2 }
    local winningRegions = 7 - #losingRegions

    if winningRegions >= #vpMinus then return end

    broadcastToAll('The US is losing in regions: ' .. message, _G.color['Blue'])
    moveVPMarkerBy('Blue', vpMinus[winningRegions + 1], 'for Global Superpower Status')
end

function securedSphereOfInfluence()
    if not _G.humanPlayers['White'] then return end -- no RU player

    local score = 0
    for _,region in ipairs(_G.zoneOfInterests['White']) do
        local zone = _G.regionScoreZone[region]
        local counts = getArmyCounts(zone)
        local max = 0
        for color,count in pairs(counts) do
            if count > max then max = count end
        end

        if counts['White'] == max and max > 0 then
            score = score + 2
        end
    end
    if score > 0 then
        moveVPMarkerBy('White', score, 'for Secured Sphere of Influence')
    end
end

function globalFDINetwork()
    -- check through CH ally zones and if there's an FDI token, check the card's GMNotes for the region
    -- store all unique regions and then for each unique region, CH scores points
    local regions = {}
    for i,zone in ipairs(_G.allyZones['Red']) do
        for _,obj in ipairs(zone.getObjects()) do
            if obj.hasTag('FDIToken') then
                local card = getFirstObject(zone, 'CountryCard')
                if card ~= nil then
                    local data = countryCardMetadata(card.getGMNotes())
                    if data ~= nil and data[6] ~= nil and data[6] ~= 'MARS' then
                        regions[data[6]] = true  -- store unique region
                    end
                end
            end
        end
    end

    local regionCount = 0
    for _ in pairs(regions) do
        regionCount = regionCount + 1
    end
    -- CH scores
    local pointsTable = { 0, 0, 0, 2, 3, 4, 6, 8 }
    score = pointsTable[regionCount + 1]
    moveVPMarkerBy('Red', score, 'for Global FDI Network (' .. regionCount .. ' regions)')
