function getRegionCounts(onlyFullyInfluenced)
    local regions = {}
    for region,zone in pairs(_G.regionScoreZone) do
        if not onlyFullyInfluenced or isRegionFullyInfluenced(region) then
            regions[region] = {}
            for color,player in pairs(_G.onlyHumans) do
                regions[region][color] = 0
            end
            for _,obj in ipairs(zone.getObjects()) do
                if obj.hasTag('InfCube') then
                    local color = getColorFromHegemonTag(obj)

                    if regions[region][color] == nil then
                        regions[region][color] = 0
                    end

                    regions[region][color] = regions[region][color] + 1
                end
            end
        end
    end
    return regions
end

function updateScores(scores, scoring, counts)
    -- Create a list of players and their cube counts for sorting
    local cubeCounts = {}
    for color, data in pairs(counts) do
        table.insert(cubeCounts, {color = color, count = data})
    end

    -- Sort players by descending cube count and count
    table.sort(cubeCounts, function(a, b)
        if a.count ~= b.count then
            return a.count > b.count
        else
            return a.count > b.count
        end
    end)

    -- Assign scores based on ranks and handle ties
    local currentScoreIndex = 1
    local i = 1
    while i <= #cubeCounts do
        local start = i
        -- Find end of tie group with same InfCube count
        while i + 1 <= #cubeCounts and
                cubeCounts[i].count == cubeCounts[i + 1].count do
            i = i + 1
        end
        local tieCount = i - start + 1

        -- Determine score to assign for this tie group
        local scoreToAssign = 0
        if currentScoreIndex + tieCount - 1 <= #scoring then
            scoreToAssign = scoring[currentScoreIndex + tieCount - 1]
        else
            scoreToAssign = 0
        end

        -- Assign score to each player in the tie group
        for j = start, i do
            if scores[cubeCounts[j].color] == nil then
                scores[cubeCounts[j].color] = { scoreToAssign }
            else
                table.insert(scores[cubeCounts[j].color], scoreToAssign)
            end
        end

        -- Move to the next group in the scoring table
        currentScoreIndex = currentScoreIndex + tieCount
        i = i + 1
    end
end

