function tradePanelClicked(args)
    local color, action, resource, doMax = args[1], args[2], args[3], args[4]

    if action == 'Produce' then
        local prerequisites = _G.productionFrom[resource]
        if prerequisites ~= nil then
            -- check if required sources are accessible
            local areMissing = false
            local missingText = ''
            for i,source in ipairs(prerequisites) do
                local s = nil
                if source == 'Coins' then
                    s = { _G.coinManager.call('updateValue', color) }
                else
                    s = getResourceCount(color, source)
                end
                if s[1] < (source == 'Coins' and 3 or 1) then
                    areMissing = true
                    missingText = missingText .. source .. ', '
                end
            end

            if areMissing then
                missingText = string.sub(missingText, 1, #missingText - 2)
                broadcastToAll(resource .. ': Missing the needed ' .. missingText .. ' for production', _G.color[color])
                return
            end

            for i,source in ipairs(prerequisites) do
                produce(color, source, source == 'Coins' and -3 or -1, false, true, true)
            end
        end

        local amount = 1
        if doMax == true then
            amount = getProduction(color, resource)
        end
        produce(color, resource, amount, false, false, true, 'produces')

    elseif action == 'Import' then
        local count = getResourceCount(color, resource)
        if resource ~= 'Army' then count = count[1] end

        if count == 10 then
            broadcastToAll(resource .. ': Full inventory', _G.color[color])
            return
        end

        local cost = -_G.tradeCosts[resource][2]
        local hasMoney = _G.coinManager.call('updateValue', color) >= cost

        if not hasMoney then
            broadcastToAll(resource .. ': Missing the needed ' .. cost .. '$ for import', _G.color[color])
            return
        end

        produce(color, resource, 1, true, false, true, (resource == 'Diplomacy' or resource == 'Army') and 'negotiates' or 'imports')
        _G.coinManager.call('subtractMoneyArgs', { color, cost, false, 'imports' })
    else
        -- export
        local count = getResourceCount(color, resource)
        local income = _G.tradeCosts[resource][1]
        local hasAny = count == 0
        if resource ~= 'Army' then hasAny = count[1] == 0 end

        if hasAny then
            local msg = resource .. ': No unit to export'
            if resource == 'Diplomacy' then msg = 'No Diplomacy to use' end
            broadcastToAll(msg, _G.color[color])
            return
        end

        produce(color, resource, -1, true, false, true, resource == 'Diplomacy' and 'negotiates' or 'exports')
        _G.coinManager.call('addMoneyArgs', { color, income, false, 'exports' })
    end
end

function importFrom(args)

    local function diploNotification(a, b)
        -- trading with Russia gives diplo only if amount is 3
        if a ~= "White" or b == 3 then
            broadcastToAll('完成本次贸易后获得1外交', _G.adminColor)
        end
    end


    local colorTo, colorFrom, amount, resource = args[1], args[2], args[3], args[4]

    local wallet = _G.coinManager.call('updateValue', colorTo)
    local cost = -_G.tradeCosts[resource][2] * amount

    if cheakGlobleEffect('RS') then
      if colorTo == 'White' and colorFrom == 'Blue' then
        broadcastToAll('对俄制裁下，俄罗斯不能与美国贸易')
        return
      end
      if colorTo == 'Blue' and colorFrom == 'White' then
        broadcastToAll('对俄制裁下，美国不能与俄罗斯贸易')
        return
      end
      if colorTo == 'White' and colorFrom == 'Yellow' then
        broadcastToAll('对俄制裁下，俄罗斯不能与欧盟贸易')
        return
      end
      if colorTo == 'Yellow' and colorFrom == 'White' then
        broadcastToAll('对俄制裁下，欧盟不能与俄罗斯贸易')
        return
      end
    end
    if cheakGlobleEffect('TW') then
      if colorTo == 'Red' and colorFrom == 'Blue' then
        broadcastToAll('中美贸易战下，中国购买美国服务额外花5$')
        cost = cost+5
      end
      if colorTo == 'Blue' and colorFrom == 'Red' then
        broadcastToAll('中美贸易战下，美国购买中国商品额外花5$')
        cost = cost+5
      end
    end


    if wallet < cost then
        broadcastToAll(resource .. ': Missing the needed ' .. cost .. '$ for import', _G.color[colorTo])
        return
    end

    if _G.humanPlayers[colorFrom] then
        -- check for available commerce card
        local card = freshCommerceCard(colorFrom)
        if card ~= nil then
            local rot = card.getRotation()
            rot.z = 180
            card.setRotationSmooth(rot, false, true)

            diploNotification(colorFrom, amount)
            broadcastToAll('Commerce Card exhausted', _G.color[colorFrom])
            produce(colorTo, resource, amount, true, false, false, 'imports')
            _G.coinManager.call('addMoneyArgs', { colorFrom, cost, true, 'sells' })
            _G.coinManager.call('subtractMoneyArgs', { colorTo, cost, true, 'imports' })

            return
        end

        -- check if inventory has resource otherwise
        local inventoryAmount = getResourceCount(colorFrom, resource)
        if inventoryAmount[1] < amount then
            broadcastToAll(_G.hegemonName[colorFrom] .. ' has insufficient ' .. resource, _G.color[colorTo])
            return
        end

        diploNotification(colorFrom, amount)
        broadcastToAll(_G.hegemonName[colorFrom] .. ' is selling from their storage.', _G.color[colorFrom])
        produce(colorFrom, resource, -amount, true, false, false, 'sells')
        _G.coinManager.call('addMoneyArgs', { colorFrom, cost, true, 'sells' })
    end

    -- transfer resources and money
    produce(colorTo, resource, amount, true, false, false, 'imports')
    _G.coinManager.call('subtractMoneyArgs', { colorTo, cost, true, 'imports' })
end

