_G.productionBuffer = {}

-- this does not produce, only holds data about what was already produced and buffers a print of resources used
-- if theres a call for addToProductionPrintBuffer, it should wait for a delay before printing out the buffer
-- if theres a call for addToProductionPrintBuffer with the same type, it should refresh the delay
-- if theres a call for addToProductionPrintBuffer with a different type, it should print the buffer immediately and start a new delay
function addToProductionPrintBuffer(color, type, count, reason)
    if _G.productionBuffer[color] == nil then
        _G.productionBuffer[color] = { type = type, count = count, timer = nil, reason = reason }
    elseif _G.productionBuffer[color].type == type then
        _G.productionBuffer[color].count = _G.productionBuffer[color].count + count
        if _G.productionBuffer[color].timer ~= nil then
            Wait.stop(_G.productionBuffer[color].timer)
        end
    else
        Wait.stop(_G.productionBuffer[color].timer)

        -- print existing buffer immediately
        if _G.productionBuffer[color].count == 0 then
            _G.productionBuffer[color] = nil
        else
            printToAll(_G.hegemonName[color] .. ' ' .. reason .. ': ' .. (_G.productionBuffer[color].count >= 0 and '+' or '') .. _G.productionBuffer[color].count .. ' ' .. _G.productionBuffer[color].type, _G.color[color])
            _G.productionBuffer[color] = { type = type, count = count, timer = nil }
        end
    end

    -- start a new timer to print after delay
    _G.productionBuffer[color].timer = Wait.time(
        function()
            printToAll(_G.hegemonName[color] .. ' ' .. reason .. ': ' .. (_G.productionBuffer[color].count >= 0 and '+' or '') .. _G.productionBuffer[color].count .. ' ' .. _G.productionBuffer[color].type, _G.color[color])
            _G.productionBuffer[color] = nil
        end,
        2)
end


function produce(color, type, count, skipCommerce, isSubproduction, isDelayedPrint, reason)
    if reason == nil then reason = '' end
    if type == 'Coins' then
        if count > 0 then
            _G.coinManager.call('addMoneyArgs', { color, count, not isDelayedPrint, reason })
        else
            _G.coinManager.call('subtractMoneyArgs', { color, -count, not isDelayedPrint, reason })
        end
    elseif type == 'Army' then
        local delay = 0
        if count > 0 then
            for i = 1,count do
                Wait.time(
                    function()
                        local tank = _G.tankBags[color].takeObject()

                        local pos = _G.readyArmyZones[color].getPosition()
                        pos.y = pos.y + 2
                        tank.setPosition(pos)
                    end,
                    delay)
                delay = delay + 0.2
            end
            addToProductionPrintBuffer(color, type, count, reason)
        elseif count < 0 then
            for i = 1,-count do
                Wait.time(
                    function()
                        local tank = getFirstObject(_G.readyArmyZones[color], 'Tank')
                        if tank.getQuantity() > 0 then
                            tank = tank.takeObject()
                        end
                        tank.destruct()
                    end,
                    delay
                    )
                delay = delay + 0.2
            end
            addToProductionPrintBuffer(color, type, count, reason)
        end
    else
        local data = getResourceCount(color, type)
        if data == nil then return end
        local goalUnlimited = data[1] + count + 1 -- this can go over 10
        local goal = math.max(1, math.min(11, goalUnlimited)) -- this is clamped to 10
        local token = data[2]
        local pos = _G.resources[color][goal].getPosition()
        local offset = table.shallow_copy(_G.resourceOffsets[type])

        if goal == 1 then
            -- since the `0` spot on the board is vertical, switch x/z and make bigger offsets
            local tmp = -offset[1] * 1.2
            offset[1] = -offset[3] * 1.4
            offset[3] = tmp
        end

        pos.x = pos.x + offset[1]
        pos.y = pos.y + offset[2]
        pos.z = pos.z + offset[3]

        token.setPosition(pos, false, true)
        token.setRotation({ 0, 180, 0}, false, true)

        if data[1] ~= goalUnlimited-1 then

            local hasOverproduced = goalUnlimited > 11 and type ~= 'Diplomacy'
            -- only print changes, otherwise just move to refresh positions on markers
            if not isSubproduction then
                if isDelayedPrint then
                    addToProductionPrintBuffer(color, type, hasOverproduced and (10 - data[1]) or count, reason)
                else
                    printToAll(_G.hegemonName[color] .. ' ' .. reason .. ': ' .. (hasOverproduced and '+' .. (10 - data[1]) or (count >= 0 and '+' or '') .. count) .. ' ' .. type, _G.color[color])
                end
            end
            if hasOverproduced then
                produce(color, 'Coins', -_G.tradeCosts[type][2] * (goalUnlimited - 11), true, false, true, 'overproduces')
            end
        end

        if not skipCommerce then
            -- flip commerce cards
            local rotated = false
            if count > 0 and table.contains(_G.exports[color], type) then
                for i,zone in ipairs(_G.commerce[color]) do
                    local card = getFirstObject(zone, 'CommerceCard')
                    if card ~= nil then
                        local rot = card.getRotation()
                        if rot.z > 90 and rot.z < 270 then
                            card.setRotationSmooth({0, 180, 0}, false, true)
                            rotated = true
                        end
                    end
                end
            end
            if rotated then
                broadcastToAll('Refreshed ' .. _G.hegemonName[color] .. ' Commerce cards', _G.color[color])
            end
        end
    end
end

function generateFDI()
    for color,player in pairs(_G.onlyHumans) do
        local money = 0
        for i,zone in ipairs(_G.allyZones[color]) do
            local count = 0
            for i,obj in ipairs(zone.getObjects()) do
                if obj.hasTag('FDIToken') then
                    if obj.getQuantity() > 1 then
                        count = count + obj.getQuantity()
                    else
                        count = count + 1
                    end
                end
            end

            if count > 0 then

                -- check for the bigger ally card, since there can be two
                local bestValue = 0
                for _, obj in ipairs(zone.getObjects()) do
                    if obj.hasTag('CountryCard') then
                        local value = countryCardMetadata(obj.getGMNotes())[5]
                        if value > bestValue then
                            bestValue = value
                        end
                    end
                end

                money = money + count * bestValue * 2  --fdi token has 2 coin per ally value
            end
        end

        if money > 0 then
            produce(color, 'Coins', money, false, false, false, 'from FDI return')
        end
    end
end

