function dealCards(numCards, color)
    local actionDeck = getFirstObject(_G.actionDeck[color], 'ActionCard')
    local discard = getFirstObject(_G.actionDiscard[color], 'ActionCard')

    -- Check if there are enough cards in the deck
    local deckCount = 0
    if actionDeck ~= nil then
        deckCount = actionDeck.getQuantity()
        if deckCount < 2 then -- singular card found
            deckCount = 1
        end
    end

    if deckCount >= numCards then
        -- Deal all required cards if the deck has enough
        actionDeck.deal(numCards, color)
    else
        -- Deal as many cards as possible from the deck
        if deckCount > 0 then actionDeck.deal(deckCount, color) end

        -- Shuffle the discard pile into the deck if possible
        if discard ~= nil then
            discard.setPositionSmooth(_G.actionDeck[color].getPosition(), false, true)  -- Move discard to deck position
            actionDeck = discard  -- Reassign deck to discard as the new deck
            Wait.time(
                function()
                    actionDeck.shuffle()  -- Shuffle the new deck

                    -- Deal the remaining required cards from the new deck
                    local remainingCards = numCards - deckCount
                    local newDeckCount = actionDeck.getQuantity()
                    if newDeckCount == -1 then
                        newDeckCount = 1
                    end
                    actionDeck.deal(math.min(remainingCards, newDeckCount), color)
                end,
                .5)
        end
    end
end

function determineHegemonOrder()
    local data = {}
    local moneys = getMajorityCoinCount()

    for i,zone in ipairs(_G.orderZones) do
        local orderMarker = getFirstObject(zone, 'OrderMarker')
        if orderMarker ~= nil then
            local color = getColorFromHegemonTag(orderMarker)

            data[color] = {}
            data[color][0] = orderMarker
            data[color][1] = getScore(color)
            data[color][2] = _G.coinManager.call('updateValue', color)
            data[color][3] = _G.startingMoney[color]
        end
    end

    local order = sortPlayersByCriteria(data)
    for i,color in ipairs(order) do
        local pos = _G.orderZones[i].getPosition()
        pos.y = pos.y + 1

        local token = data[color][0]

