function takeHand(row, color)

    _G.playerBoards[color].removeButton(0)
    _G.playerBoards[color].removeButton(1)

    local index = row == 1 and 2 or 1
    for _,obj in ipairs(_G.hands[color][index].getObjects()) do
        if obj.hasTag('ActionCard') then
            obj.setPosition(_G.actionDeck[color].getPosition(), false, true)
            obj.setRotation({0, 180, 180}, false, true)
        end
    end

    Wait.frames(
        function()
            if row == 2 then
                -- move all cards from hand 2 to hand 1
                for _,obj in ipairs(_G.hands[color][2].getObjects()) do
                    if obj.hasTag('ActionCard') then
                        obj.setPosition(_G.hands[color][1].getPosition(), false, true)
                    end
                end
            end
            -- shuffle the deck and give asset cards
            Wait.time(
                function()
                    getFirstObject(_G.actionDeck[color], 'ActionCard').shuffle()
                    _G.hands[color][2].destruct()
                    local assetDeck = getFirstObject(_G.assetDeck[color], 'AssetCard')
                    if assetDeck == nil or assetDeck.getQuantity() < 5 then
                        broadcastToAll('Not enough Asset cards to deal for ' .. _G.hegemonName[color] .. '. Reload the mod.', _G.adminColor)
                        return
                    end
                    assetDeck.shuffle()
                    assetDeck.deal(3, color)
                    broadcastToColor('Keep 2 Asset Cards - Place them below the Asset Deck.', color, _G.adminColor)
                end,
                1)
        end,
        1)
end

function scoreAssets()
    for color, player in pairs(_G.onlyHumans) do
        local vp = 0
        for i, zone in ipairs(_G.assetCards[color]) do
            local card = getFirstObject(zone, 'AssetCard')
            if (card == nil) then
                broadcastToAll('Could not locate ' .. i .. '. Asset card for ' .. _G.hegemonName[color] .. '.', _G.adminColor)
            elseif card.hasTag('AssetCard') then
                card.setRotationSmooth({0, 180, 0}, false, true)
                vp = vp + tonumber(string.sub(card.getGMNotes(), 1, 1))
            end
        end
        moveVPMarkerBy(color, vp, 'for starting Asset cards')
    end
end

function table.shuffle(tbl)
    for i = #tbl, 2, -1 do
        local j = math.random(i)  -- Get a random index between 1 and i
        tbl[i], tbl[j] = tbl[j], tbl[i]  -- Swap elements
    end
end

