function sortPlayersByCriteria(data)
    -- Create a sortable array from the data table
    local sortableData = {}
    for color, values in pairs(data) do
        table.insert(sortableData, {color = color, val1 = values[1], val2 = values[2], val3 = values[3]})
    end

    -- Sort the array with the criteria: least val1, then least val2, then least val3
    table.sort(sortableData, function(a, b)
        if a.val1 ~= b.val1 then
            return a.val1 < b.val1
        elseif a.val2 ~= b.val2 then
            return a.val2 < b.val2
        else
            return a.val3 < b.val3
        end
    end)

    -- Create the result array with sorted colors
    local sortedColors = {}
    for _, player in ipairs(sortableData) do
        table.insert(sortedColors, player.color)
    end

    return sortedColors
end

