function researchPhase()

    if getRoundNumber() == 6 then
        Wait.frames(function()
            broadcastToAll('根据规则，第六轮的研究阶段被完全跳过', _G.adminColor)
            _G.phaseManager.call('advancePhase')
        end, 1)
        return false
    end

    local delay = 1
    discardPlayedCards()

    -- research cards
    -- remove player cards from hand
    Wait.time(
        function()
            for color,player in pairs(_G.onlyHumans) do
                local handObjects = player.getHandObjects()
                local startPosition = _G.playedCardZones[color].getPosition()

                -- Calculate starting X position for layout (centering cards around the zone)
                local offset = 1
                local totalWidth = (#handObjects - 1) * offset
                local startX = startPosition.x - (totalWidth / 2)

                -- Arrange each card with the offset
                for i, card in ipairs(handObjects) do
                    local targetPosition = {
                        x = startX + (i - 1) * offset,
                        y = startPosition.y + 1 + (i - 1) * .5,
                        z = startPosition.z
                    }

                    card.setPosition(targetPosition)
                    card.setRotation({ 0, 180, 0})
                end
            end
        end,
        delay
    )
    delay = delay + 1

    Wait.time(
        function()

            local function calculateResources(gm_notes, resources)
                local research = string.sub(gm_notes, 1, 1)
                local otherCount = string.sub(gm_notes, 2, 2)
                local otherType = string.sub(gm_notes, 3, 3)
                resources[1] = resources[1] + tonumber(research)
                local index = otherType == 'C' and 2 or (otherType == 'D' and 3 or 4)
                if otherCount == '0' then otherCount = 10 end -- 10 has the '0' digit
                resources[index] = resources[index] + tonumber(otherCount)
            end

            local focuses = checkHegemonFocuses()
            for color, player in pairs(_G.onlyHumans) do
                local resources = { 0, 0, 0, 0 } -- research, coins, diplomacy, tanks
                local color = player.color
                local playerZone = _G.playedCardZones[color]

                if focuses[color] == 'Domestic' then resources[1] = 2 end

                for i,card in ipairs(playerZone.getObjects()) do
                    if card.hasTag('ActionCard') then
                        if card.getQuantity() == -1 then
                            calculateResources(card.getGMNotes(), resources)
                        else
                            for i,c in ipairs(card.getObjects()) do
                                calculateResources(c.gm_notes, resources)
                            end
                        end
                    end
                end

                local message = '研究阶段收入：' .. resources[1] .. ' 研究点'
                if resources[2] > 0 then message = message .. ', ' ..  resources[2] .. '$' end
                if resources[3] > 0 then message = message .. ', ' ..  resources[3] .. ' 外交' end
                if resources[4] > 0 then message = message .. ', ' ..  resources[4] .. ' 军队' end
                broadcastToAll(message, _G.color[color])

                Wait.frames(
                    function ()
                        if resources[1] > 0 then setResearch(color, resources[1]) end
                        if resources[2] > 0 then produce(color, 'Coins', resources[2], true, false, false, 'researches') end
                        if resources[3] > 0 then produce(color, 'Diplomacy', resources[3], true, false, false, 'researches') end
                        if resources[4] > 0 then produce(color, 'Army', resources[4], true, false, false, 'researches') end
                    end,
                    1
                )
            end
        end,
        delay)
    delay = delay + 1

    Wait.time(function() broadcastToAll('进行研究，然后进入事件阶段。', _G.adminColor) end, delay)
    return false
end

