function aftermathContinued()

    -- resolve threat (returns delay in seconds)
    local delay = resolveThreat()

    if getRoundNumber() % 3 == 0 then
        -- score regions
        Wait.time(scoreInfluence, delay)
        delay = delay + 2

        -- score majority tokens
        Wait.time(scoreMajorityTokens, delay)
        delay = delay + 2

        -- Superpower Overstretch
        if _G.humanPlayers['Blue'] then
            Wait.time(superpowerOverstretch, delay)
            delay = delay + 1
        end

        -- Secured Sphere of Influence
        if _G.humanPlayers['White'] then
            Wait.time(securedSphereOfInfluence, delay)
            delay = delay + 1
        end
    end

    local roundNumber = getRoundNumber()
    Wait.time(
        function()
            broadcastToAll('Round ' .. roundNumber .. ' ended', _G.adminColor)
        end,
        delay)

    -- advance: preparationPhase()
    local isGameOver = roundNumber > 5

    if isGameOver then
        Wait.time(gameOver, delay + 1)
