function gameOver()
    broadcastToAll('--- End Game Scoring ---', _G.adminColor)
    -- calculate end-game scoring
    -- all unused asset cards (flipped up) are worth 2 VP each
    local delay = 1
    for color, player in pairs(_G.onlyHumans) do
        local vp = 0
        for _, zone in ipairs(_G.assetCards[color]) do
            local card = getFirstObject(zone, 'AssetCard')
            if card ~= nil then
                local rot = card.getRotation()
                if rot.z > 270 or rot.z < 90 then
                    vp = vp + 2
                end
            end
        end

        if _G.executiveOrderCards[color] ~= nil then
            -- unused Executive Order cards are worth 3 VP
            local rot = _G.executiveOrderCards[color].getRotation()
            if rot.z > 270 or rot.z < 90 then
                vp = vp + 3
            end
        end

        -- delayed show to allow for the VP marker to be moved
        Wait.time(
            function()
                moveVPMarkerBy(color, vp, 'for unused Asset/Executive Order cards')
            end,
            delay)
        delay = delay + 1
    end

    -- Global FDI Network
    if _G.humanPlayers['Red'] then
        Wait.time(globalFDINetwork, delay + 1)
    end

    -- sort and show end game results
    Wait.time(sortPlayersAndShowGameOver, delay + 2)
end

function sortPlayersAndShowGameOver()
    local data = {}
    local regionalInfluences = getRegionCounts(false)

    for color,isHuman in pairs(_G.humanPlayers) do
        data[color] = { 0, 0, 0 }
        if isHuman then
            -- sorting works in reverse, least gets first place, so to flip it, using negative numbers
            data[color][1] = -getScore(color)
        end
    end
    data['Black'] = { 0, 0, 0 }

    local winningRegions = {}
    for region,colors in pairs(regionalInfluences) do
        local max = -1
        local localWinner
        for color,cubes in pairs(colors) do
            if data[color][3] == nil then
                data[color][3] = cubes
            else
                data[color][3] = data[color][3] + cubes
            end
            if cubes > max then
                max = cubes
                localWinner = color
            elseif cubes == max then
                localWinner = nil
            end
        end

        if localWinner ~= nil then
            if data[localWinner][2] == nil then
                data[localWinner][2] = 1
            else
                data[localWinner][2] = data[localWinner][2] + 1
            end
        end
    end

    for color, type in pairs(data) do
        data[color][2] = -data[color][2]
        data[color][3] = -data[color][3]
    end

    local sortedColors = sortPlayersByCriteria(data)
    local place = 1
    local prev
    local messages = {}
    for i,color in ipairs(sortedColors) do
        if _G.humanPlayers[color] then
            if prev ~= nil and (
                data[color][1] ~= data[prev][1] or
                data[color][2] ~= data[prev][2] or
                data[color][3] ~= data[prev][3]) then
                place = place + 1
            end
            prev = color
            table.insert(messages, { place .. '. ' .. _G.hegemonName[color] .. ' (' .. -data[color][1] .. ' VP)', _G.color[color] })
        end
    end

    for i=#messages,1,-1 do
        broadcastToAll(messages[i][1], messages[i][2])
    end
end

